def find_good_drawing(n, m, points, segments):
    from itertools import product

    # Try all possible combinations of colors for points
    for colors in product([0, 1], repeat=n):
        valid = True
        for l, r in segments:
            red_count = blue_count = 0
            for i in range(n):
                if l <= points[i] <= r:
                    if colors[i] == 0:
                        red_count += 1
                    else:
                        blue_count += 1
            if abs(red_count - blue_count) > 1:
                valid = False
                break
        if valid:
            return colors
    return -1

